import { useState } from 'react';
import { JxButton, JxField, JxInput, JxSelect, JxOption, JxSwitch } from '@jinx-ui/react';

// Названия полей Select/Switch взяты по контракту value + onValueChange из README.
// Если в вашей версии @jinx-ui/react опции задаются пропом options, замените JxOption на него.

export type ProfileSettings = {
  name: string;
  language: 'ru' | 'en';
  emailNotifications: boolean;
};

type ProfileSettingsFormProps = {
  initialSettings?: Partial<ProfileSettings>;
  onSave: (settings: ProfileSettings) => void;
};

export default function ProfileSettingsForm({ initialSettings, onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState<ProfileSettings['language']>(initialSettings?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(initialSettings?.emailNotifications ?? false);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name: name.trim(), language, emailNotifications });
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}
    >
      <JxField label="Имя" htmlFor="profile-name">
        <JxInput
          id="profile-name"
          value={name}
          onValueChange={setName}
          placeholder="Введите имя"
          autoComplete="name"
        />
      </JxField>

      <JxField label="Язык интерфейса" htmlFor="profile-language">
        <JxSelect
          id="profile-language"
          value={language}
          onValueChange={(next: string) => setLanguage(next as ProfileSettings['language'])}
        >
          <JxOption value="ru">Русский</JxOption>
          <JxOption value="en">Английский</JxOption>
        </JxSelect>
      </JxField>

      <JxSwitch
        checked={emailNotifications}
        onCheckedChange={setEmailNotifications}
        label="Уведомления на почту"
      />

      <JxButton type="submit" variant="primary">
        Сохранить
      </JxButton>
    </form>
  );
}

